BASE=Path(__file__).resolve().parents[1];OUT=BASE/'.cache/batch200/drafts/rewrite_vid'
def S(w):return 'https://www.etymonline.com/word/'+w
def O(w):return 'https://www.oxfordlearnersdictionaries.com/definition/english/'+w
BELL=['拉丁 bellum → bellare','战争 → 作战']
REB=['拉丁 rebellare／rebellis','反抗、重新作战／反抗的']
GER=['拉丁 bellum + gerere → belligerare／belligerans','战争 + 进行 → 进行战争／正在作战的']
W=[
E('rebel','英美：名词、形容词 /ˈrebl/；动词 /rɪˈbel/','反叛者；不愿服从的人；反叛；抵抗','别人说“照规矩来”，这个人却站到规矩对面，说“我不接受”。','远源是拉丁 re- + bellare“作战”，re- 可理解为反过来或再一次。名词、形容词接古法语 rebelle 与拉丁 rebellis；动词另经古法语 rebeller、拉丁 rebellare，不是简单把现代英语名词转成动词。',[BELL,REB,['古法语 rebelle；rebeller','反抗者、反抗的；反抗'],['英语 rebel','人物称呼与形容词重读前部；动词重读后部']],'新闻里的 rebels 可能是武装反叛者；公司、政党或家庭里的 a rebel 也可能只是拒绝服从的人。词本身没有替你判定这人正义还是错误，具体态度来自上下文。','rebel against authority；rebel forces；a rebel within the party；a bit of a rebel。','名词 a rebel 是 /ˈrebl/，动词 to rebel 是 /rɪˈbel/。动词常接 against，过去式 rebelled、进行式 rebelling 都双写 l。',('The novel follows a rebel who refuses to serve the king.','这部小说讲述一个拒绝为国王效力的反叛者。'),('She was the family rebel who chose a completely different career.','她是家里那个不按常规走的人，选了完全不同的职业。'),('The students rebelled against the new dress code.','学生们反对新出台的着装规定。'),sources=[S('rebel'),O('rebel_1'),O('rebel_2')]),
E('rebellion','英美 /rɪˈbeljən/','反叛；起义；抗拒、叛逆行为','把一个人的“不服”扩大成一场行动，或把内心拒绝服从的劲头当成一件事来说。','来自古法语 rebellion，也可直接接拉丁 rebellio、宾格 rebellionem；拉丁名词与 rebellis“反抗的”相连。现代能联想 rebel + -ion，但历史不是英语临时加后缀造出的名词。',[BELL,REB,['拉丁 rebellio → 古法语 rebellion／拉丁直接借入','反叛；重新开战'],['中古英语 rebellioun → rebellion','反叛行动；引申为抗拒权威']],'a rebellion 常是一场反抗事件；teenage rebellion 则常指青少年的抗拒倾向，不必涉及暴力。in rebellion against 表示以行动反对某种权威或规矩。','a rebellion against the ruler；an act of rebellion；teenage rebellion；in open rebellion。','rebellion 讲反抗本身，不保证成功改变制度；revolution 常突出较根本的改变。rebelliousness 更常概括一个人的叛逆性情。',('The history book explains why the rebellion spread to nearby towns.','这本历史书解释了这场反叛为何蔓延到邻近城镇。'),('For him, refusing the family business was an act of rebellion.','对他来说，拒绝接手家族生意是一种反抗。'),sources=[S('rebellion'),S('rebel'),O('rebellion')]),
E('rebellious','英美 /rɪˈbeljəs/','叛逆的；反抗的；不服管束的','不只是心里有不同看法，而是身上带着“你越规定，我越想挣开”的劲头。','与 rebel 一族相连；可按 rebel + -ious 理解，词源书也从拉丁 rebellis 加 -ous 分析。它在中古英语时期已出现，不是从现代名词 rebellion 简单删掉结尾得到的。',[BELL,REB,['中古英语 rebellious','在 rebel／拉丁 rebellis 的基础上形成形容词'],['现代英语 rebellious','反抗权威、不服管束；也可形容难以控制的东西']],'a rebellious teenager 说孩子不愿遵守规则；a rebellious faction 说一个派别不愿服从领导。发型、音乐或穿着也能显得 rebellious，表达挑战常规的态度。','a rebellious streak；a rebellious attitude；rebellious teenagers；rebellious members。','independent 可以只是有主见，不一定反抗谁。rebellious 则突出与权威或既有规则发生对抗，评价可正可负。',('Her rebellious streak made her question every school rule.','她那股叛逆劲让她对每条校规都提出质疑。'),('The band kept its rebellious energy even after becoming famous.','这支乐队成名后仍保留着挑战常规的劲头。'),sources=[S('rebellious'),O('rebellious'),'https://en.wiktionary.org/wiki/rebellious']),
E('rebelliously','英美 /rɪˈbeljəsli/','反抗地；带着叛逆态度地','同一句话，可以平静地说，也可以带着“我偏不听”的口气说；这个词描述后者。','英语 rebellious + -ly，表示以叛逆、不服从的方式。它把形容人的态度变成对说话、穿着或行动方式的描述。',[BELL,REB,['英语 rebellious → rebelliously','叛逆的 → 以叛逆方式行动']],'answered rebelliously 不是说回答声音一定很大，而是回答里有抗拒服从的意思。也可用来描写不按传统期待穿衣、创作或生活。','reply rebelliously；act rebelliously；dress rebelliously；smile rebelliously。','angrily 重点是愤怒，rebelliously 重点是抗拒权威或约束；一个人可以平静而叛逆，也可以生气却仍然服从。',('He rebelliously kept his hat on after being asked to remove it.','被要求摘帽后，他偏不照办，仍戴着帽子。'),('The young designer mixed formal suits with rebelliously bright shoes.','这位年轻设计师把正装和刻意打破常规的鲜亮鞋子搭在一起。'),sources=[O('rebelliously'),S('rebellious')]),
E('rebelliousness','英美 /rɪˈbeljəsnəs/','叛逆性；不服管束的倾向','不是哪一次具体反抗，而是一个人身上常有的“不想照你安排”的性情。','英语 rebellious + -ness，把叛逆的性质或状态名词化。-ness 不增加“更严重”或“很多次”的含义。',[BELL,REB,['英语 rebellious + -ness','叛逆的 → 叛逆性、不服从的倾向']],'谈一个孩子、艺术家或群体的 rebelliousness，常是在概括一种持续的态度。它既可能惹来冲突，也可能表现为敢于质疑传统，不能一见这个词就译成犯罪倾向。','teenage rebelliousness；a streak of rebelliousness；signs of rebelliousness。','rebellion 更容易指一场或一次反抗；rebelliousness 通常不可数，更强调特质、倾向。',('Her early rebelliousness later became a willingness to challenge outdated ideas.','她早年的叛逆后来变成了敢于挑战过时观念的态度。'),('The teacher saw frustration behind his apparent rebelliousness.','老师从他表面上的不服管束看出了挫败感。'),sources=[O('rebelliousness'),S('rebellious'),'https://en.wiktionary.org/wiki/rebelliousness']),
E('bellicose','英 /ˈbelɪkəʊs/；美 /ˈbelɪkoʊs/','好战的；好斗的','还没动手，话里已经像在摆出要开战的架势。','直接接拉丁 bellicosus“好战的”，由 bellicus“战争的”进一步形成，根是 bellum“战争”。结尾 -ose 接拉丁 -osus 的形容词形式，不是英语 bell“铃”加后缀。',[['拉丁 bellum → bellicus','战争 → 与战争有关的'],['拉丁 bellicosus','好战、勇战、好斗的'],['中古英语 → bellicose','好斗、摆出冲突姿态的']],'常见于政治评论，说 bellicose rhetoric 时通常在批评好战言辞。也可描述个人爱争吵的态度；并不表示已经真的开战。','bellicose rhetoric；a bellicose tone；bellicose statements；a bellicose leader。','bellicose 常突出好斗倾向，belligerent 也可指咄咄逼人，但在正式战争语境还有“交战的、交战方”义。两词有重叠，不能只靠中文一个“好战”完全替换。',('The editorial criticized the minister’s bellicose rhetoric.','社论批评了这位部长的好战言辞。'),('His bellicose tone turned a small disagreement into an argument.','他好斗的口气把一点小分歧变成了争吵。'),sources=[S('bellicose'),O('bellicose'),'https://en.wiktionary.org/wiki/bellicose']),
E('belligerence','英美 /bəˈlɪdʒərəns/','好斗、挑衅的态度或行为；交战状态','谈话本来可以合作进行，却处处像在迎战；这种挑衅劲就是日常语境里的 belligerence。','英语 belligerent 的 -ent 改为名词形式 -ence。较早的 belligerent 接拉丁 belligerans“正在作战的”，其中 belli- 是战争，-ger- 接 gerere“进行、承载”。',[GER,['英语 belligerent','交战的；好斗的'],['belligerent → belligerence','这种态度、行为或交战状态']],'日常写作常说 with belligerence，强调说话或行为带着攻击性。历史、外交文字中也可能讨论实际交战的状态，不能一律理解成脾气暴躁。','a tone of belligerence；respond with belligerence；growing belligerence；military belligerence。','confidence 是自信，不必向别人挑衅；belligerence 暗示把互动变成对抗。是否指正式交战，要看战争或外交上下文。',('The customer’s belligerence made the discussion increasingly difficult.','那位顾客咄咄逼人的态度让交谈越来越困难。'),('The report traced the shift from negotiation to open belligerence.','报告梳理了从谈判转向公开交战的过程。'),sources=[S('belligerence'),O('belligerence'),'https://en.wiktionary.org/wiki/belligerence']),
E('belligerently','英美 /bəˈlɪdʒərəntli/','咄咄逼人地；挑衅地；以好战方式','不是单纯把立场说清，而是说话或行动时像要逼对方接招。','英语 belligerent + -ly；拉丁祖先 belligerans 是 belligerare“进行战争”的现在分词。形容词变副词后，描述的是行动方式。',[GER,['英语 belligerent → belligerently','好斗的 → 以挑衅、好斗方式']],'可以修饰问话、回应、拒绝或发表立场。哪怕没有高声喊叫，步步逼迫、带着敌意的回应也能是 belligerently。','ask belligerently；respond belligerently；behave belligerently；speak belligerently。','firmly 是坚定地，未必不友善；belligerently 多了一层攻击、找冲突的态度。',('He leaned across the table and asked belligerently who had made the decision.','他探身越过桌子，咄咄逼人地追问是谁作的决定。'),('The spokesperson responded belligerently instead of addressing the concern.','发言人没有回应那项担忧，而是以挑衅态度作答。'),sources=[O('belligerently'),S('belligerent'),'https://en.wiktionary.org/wiki/belligerent']),
E('duel','英 /ˈdjuːəl/；美 /ˈduːəl/','决斗；两方较量；进行决斗、对决','把较量缩成两方正面对上：历史小说里可能是持械决斗，比赛报道里可能只是势均力敌的竞争。','接中古拉丁 duellum“两人决斗”，有经法语传入的分析。更早 duellum 本来是 bellum“战争”的古拉丁形式，后来受 duo“二”等词联想影响，意思收窄；并非最初就按“两个人”造词。',[['古拉丁 duellum；后来通常作 bellum','战争'],['中古拉丁 duellum','受“二”的联想影响，专指两人较量、决斗'],['英语 duel 名词 → 动词','决斗或两方竞争 → 进行这种较量']],'历史中的 a duel 常是事先约定、涉及名誉的两人持械冲突。现代 a verbal duel 是唇枪舌剑，a duel between runners 是两名跑者争胜，都没有要求真实使用武器。','a duel between two rivals；a verbal duel；fight a duel；duel with an opponent。','dual 的意思是双重的，和 duel 读音接近，却不是同一个词。历史上 duo 的联想改变了 duellum 的意义，不等于可以把现代 duel 拆成 du + el。',('In the novel, the two officers arrange a duel at dawn.','小说中，两名军官约定在黎明决斗。'),('The final lap became a duel between the two leading runners.','最后一圈变成了两名领先选手的对决。'),('The two candidates dueled over the budget during the debate.','两位候选人在辩论中围绕预算展开了交锋。'),sources=[S('duel'),O('duel_1'),'https://en.wiktionary.org/wiki/duel']),
E('revel','英美 /ˈrevəl/','狂欢；尽情享受；喧闹的欢庆活动','原来的“闹起来”慢慢走向“玩得尽兴”，再走向非常享受某种感受。','动词经古法语 reveler，名词经古法语 revel／resvel 分别借入；法语这支远接拉丁 rebellare“反抗”。反抗、骚动、喧闹欢乐的转义发生在较早历史中，不是现代英语 rebel 改一个字母才得到 revel。',[BELL,REB,['古法语 reveler；revel／resvel','骚动、纵情欢乐；喧闹欢庆'],['中古英语 revelen／revel → revel','狂欢；后来 revel in 表示十分喜欢、尽情享受']],'revel in praise 是陶醉于赞扬，revel in the quiet 甚至可以是尽享安静，未必吵闹。单独用 revel 作动词较偏书面，名词复数 revels 常见于节庆或文学描写。','revel in success；revel in freedom；revel in doing something；nighttime revels。','enjoy 很普通，revel in 更像沉浸其中、乐在其中。reveal“揭示”另有来源，拼写相近却不是同一动词。',('After weeks of deadlines, she revelled in a quiet afternoon at home.','连续几周赶截止日期后，她尽情享受了一个安静的居家下午。'),('The villagers revelled late into the night after the harvest.','收获之后，村民们欢庆到深夜。'),('The street revels continued until the rain began.','街头欢庆一直持续到开始下雨。'),sources=[S('revel'),O('revel-in'),'https://en.wiktionary.org/wiki/revel']),
E('revelry','英美 /ˈrevəlri/','喧闹的欢乐；狂欢、欢庆','笑声、音乐、聚会和欢呼混在一起，整个场面热闹起来。','中古英语 revelrie，英语 revel 名词加 -ery／-ry 形成。revel 本身经古法语表示喧闹欢乐的词借入，远源与 rebellare 的反抗、骚动有关。',[BELL,REB,['古法语 revel → 英语 revel','骚动的转义支线成为喧闹欢庆'],['英语 revel + -ry → revelry','欢庆活动或热闹场面']],'通常不可数，a night of revelry 说一夜欢庆。复数 revelries 则可概括多场或一连串欢庆活动，常见于节日描写；不自动意味着违法或闹事。','a night of revelry；New Year revelry；join the revelry；festive revelries。','celebration 更广，可以安静庄重；revelry 常带喧闹、尽情作乐的感觉。',('Music and revelry filled the square after the parade.','游行结束后，广场上满是音乐声和欢庆声。'),('She left the revelry early and walked home through the quiet streets.','她早早离开热闹的庆祝场面，沿着安静的街道步行回家。'),sources=[S('revelry'),O('revelry'),'https://en.wiktionary.org/wiki/revelry']),
E('reveller','英 /ˈrevələ/；美 /ˈrevələr/','狂欢者；参加热闹欢庆的人；美式拼 reveler','镜头不再拍整个聚会，而是拍聚会里唱歌、跳舞、欢庆的那些人。','现代可看作 revel + -er；历史上中古英语 revelour 借自古法语同形词，后者由 reveler“纵情欢乐”形成。它并非一定是在现代英语里新造出的职业名。',[BELL,REB,['古法语 reveler → revelour','喧闹欢乐 → 参与欢乐的人'],['中古英语 revelour → reveller／reveler','欢庆参与者；现代英美拼写不同']],'新闻里的 New Year revellers 是跨年欢庆的人群，不限专业表演者，也不保证每个人都喝酒。这个词指他们当时的活动角色，而不是固定职业。','New Year revellers；late-night revellers；a crowd of revellers；festival revellers。','reveller 是人，revelry 是活动或场面。British reveller 双写 l，American reveler 常单写 l，指的是同一类人。',('Revellers gathered in the square to welcome the new year.','欢庆的人们聚集在广场上迎接新年。'),('The last few revellers left the festival as the sun rose.','太阳升起时，最后几位狂欢者离开了节庆现场。'),sources=[S('reveler'),O('reveller')]),
]
ROOT=dict(id='C0116',meaning='战争；作战',core='拉丁 bellum 是战争。它进入英语后，一条线保留好战、交战，另一条线说反抗权威；还有一条更远的法语支线从骚动转成欢庆。',image='bellum 战争 → belligerent、bellicose；re- + bellare → rebel、rebellion；同一反抗支线在法语里转义 → revel；古形式 duellum → duel。',intro='不要拿英语 bell“铃”去猜这组词。先区分谁在反抗、谁显得好斗，再认识 duel 与 revel 这两个外形不明显的亲戚；它们保存的是历史变化，不是今天一个固定的“战争”译法。',forms='bell-、belli- 接 bellum；bellare 是作战。re- 在 rebellare 中有反过来、重新的解释。古拉丁 duellum 后来形成现代常见 bellum，旧形式又在中古拉丁发展出决斗义；更早来源不确定。',branches=[['反抗与叛逆','rebel, rebellion, rebellious, rebelliously, rebelliousness'],['好斗、交战与战前','bellicose, belligerent, belligerence, belligerently, antebellum'],['从战争旧词形到两方对决','duel'],['从骚动转向欢庆与尽享','revel, revelry, reveller']],contrasts='bell“铃”不同源。rebel 的名词和动词重音不同；rebellion 并非必定从英语动词派生。revel 与 reveal 不同。duel 后来的“两方”义受到 duo 联想影响，不能把这个影响误写成最早的造词来源。',practice='The rebel enjoyed the revelry after the debate. 那个不服从常规的人在辩论后享受欢庆：rebel 描述人物态度，revelry 描述欢乐场面，二者在现代语境并不等义。',words=[],exclude={})
if __name__=='__main__':
 m=json.loads((BASE/'.cache/batch200/rewrite_vid.json').read_text());r=next(x for x in m['roots'] if x['id']==ROOT['id']);ROOT['words']=[w for w in r['family'] if '-' not in w]
 assert set(ROOT['words'])=={e['word'] for e in W}|{'belligerent','antebellum'}
