 for kind,data in [('roots',[ROOT]),('words',W)]: (OUT/(kind+'_batch200_vid_116.json')).write_text(json.dumps(data,ensure_ascii=False,indent=2))
 print('bell:',len(W),'words;',sum(len(e['examples']) for e in W),'examples;',len(ROOT['words']),'references')
